function drawGround(){let x0=Math.floor(camera.x/T),y0=Math.floor(camera.y/T),x1=x0+31,y1=y0+18;for(let y=y0;y<=y1;y++)for(let x=x0;x<=x1;x++){tile(x,y);if(y>=31&&y<=32)rect(x*T-camera.x,y*T-camera.y,T,T,biome(x)<2?'#806c52':biome(x)===2?'#8a8069':'#7b554a');if(x>=23&&x<=24&&y>29&&y<35)rect(x*T-camera.x,y*T-camera.y,T,T,'#827057')}}
function drawProps(){let x0=Math.floor(camera.x/T)-1,y0=Math.floor(camera.y/T)-2;
 for(let y=y0;y<y0+22;y++)for(let x=x0;x<x0+34;x++){if(x<1||x>=MW-1||y<1||y>=MH-1)continue;let r=hash(x*11+8,y*23-4);let b=biome(x);let skip=(y>=30&&y<=34)||(x>=17&&x<=21&&y>=29&&y<=35)||(x>=40&&x<=44&&y>=23&&y<=29)||(x>=60&&x<=64&&y>=34&&y<=40)||(x>=87&&x<=94&&y>=28&&y<=36);
 if(skip)continue;if(r>(b===1?.83:.9)){let px=x*T+8,py=y*T+11;tree(px,py,b)}else if(r>.985){rock(x*T+8,y*T+11,b===2?1:0)}}
 // scenic pools
 for(const p of [[11,18,3,2],[32,46,3,2],[56,15,3,2],[77,19,3,2]]){let [x,y,w,h]=p,sx=x*T-camera.x,sy=y*T-camera.y;for(let yy=0;yy<h;yy++)for(let xx=0;xx<w;xx++){let rr=hash(x+xx,y+yy);rect(sx+xx*T,sy+yy*T,T,T,biome(x)===3?'#573d43':'#355c68');rect(sx+xx*T+3,sy+yy*T+5,4,1,biome(x)===3?'#a16a55':'#669293');if(rr>.7)rect(sx+xx*T+10,sy+yy*T+10,3,2,'#416c72')}}
 drawShrine(seals[0],'#e8c66c');drawShrine(seals[1],'#7ce0a5');drawShrine(seals[2],'#a4a8f5');drawCastle();drawCamp();}
function drawShrine(s,color){let x=s.x-camera.x,y=s.y-camera.y;rect(x-15,y-2,30,9,'#292734');rect(x-12,y-8,24,7,'#72644e');rect(x-8,y-13,16,6,'#a49470');rect(x-5,y-18,10,7,'#544e4c');rect(x-2,y-22,4,6,color);rect(x-1,y-20,2,2,'#fff5bf');if(!s.got){let pulse=1+Math.sin(Date.now()/210)*.2;ctx.globalAlpha=.25;rect(x-10,y-35,20,20,color);ctx.globalAlpha=1;rect(x-2*pulse,y-31,4*pulse,9*pulse,color);rect(x-1,y-34,2,4,'#fff5bf')}}
function drawCastle(){let x=88*T-camera.x,y=32*T-camera.y;rect(x-39,y-4,78,20,'#221b27');rect(x-34,y-36,68,34,'#48333b');rect(x-28,y-43,12,17,'#5e3b40');rect(x-11,y-49,17,25,'#392b39');rect(x+13,y-42,14,18,'#553940');for(let i=-31;i<35;i+=12)rect(x+i,y-44+(i%2?7:0),6,9,'#302633');rect(x-5,y-16,10,13,'#160f1c');rect(x-20,y-25,5,5,'#ffb25d');rect(x+15,y-25,5,5,'#ffb25d');rect(x-2,y-54,4,7,'#b7474a');}
function drawCamp(){let x=8*T-camera.x,y=32*T-camera.y;rect(x-20,y+10,40,2,'#a48960');rect(x-14,y+3,12,6,'#a67e48');rect(x+5,y+4,10,5,'#6a8055');rect(x+1,y+8,7,3,'#e58b48');rect(x+3,y+5,3,3,'#ffd678')}
function drawSealSprites(){for(const s of seals)if(!s.got){let x=s.x-camera.x,y=s.y-camera.y-31;let bob=Math.sin(Date.now()/220+s.x)*2;rect(x-3,y+bob,6,6,s.name==='MEADOW SEAL'?'#f4d276':s.name==='VERDANT SEAL'?'#89e3a8':'#abb3ff');rect(x-1,y-2+bob,2,2,'#fff5cb')}}
function drawHero(){let x=player.x-camera.x,y=player.y-camera.y;let blink=player.iframes>0&&Math.floor(Date.now()/70)%2;if(blink)return;rect(x-5,y+5,10,3,'#20222b');let tunic=player.attack>0?'#ead28f':'#5d85a4';rect(x-5,y-7,10,12,tunic);rect(x-4,y-8,8,2,'#dbc89b');rect(x-4,y-13,8,7,'#f1bd8b');rect(x-5,y-16,10,4,'#76584d');rect(x-4,y-18,8,3,'#d7c78e');rect(x-3,y-11,2,2,'#252638');rect(x+2,y-11,2,2,'#252638');rect(x-4,y+4,3,4,'#463c45');rect(x+2,y+4,3,4,'#463c45');if(player.attack>0){let a=player.attack;let dx=player.dir==='left'?-1:player.dir==='right'?1:0,dy=player.dir==='up'?-1:player.dir==='down'?1:0;let sx=x+dx*10,sy=y+dy*8;rect(sx-2,sy-2,4,4,'#fff2bc');rect(sx+(dy?4:0)-1,sy+(dx?4:0)-1,3,3,'#9ee3ed');rect(sx+(dy?-4:0)-1,sy+(dx?-4:0)-1,3,3,'#fff2bc')}}
function drawFoe(f){if(!f.alive)return;let x=f.x-camera.x,y=f.y-camera.y+(f.stun>0?Math.sin(Date.now()/30)*2:0);if(f.type==='king'){rect(x-11,y+7,22,4,'#231a27');rect(x-9,y-9,18,18,'#522d42');rect(x-7,y-16,14,10,'#713849');rect(x-10,y-18,5,7,'#bb574b');rect(x+5,y-18,5,7,'#bb574b');rect(x-6,y-23,12,5,'#e08a50');rect(x-5,y-5,4,3,'#ffca69');rect(x+2,y-5,4,3,'#ffca69');rect(x-3,y+6,6,7,'#241925');if(f.hp<f.max){rect(x-12,y-28,24,3,'#24151d');rect(x-11,y-27,22*f.hp/f.max,1,'#e45450')}}else if(f.type==='brute'){rect(x-7,y+6,14,3,'#292932');rect(x-7,y-6,14,13,'#684754');rect(x-5,y-12,10,8,'#88515a');rect(x-6,y-14,4,5,'#c7735d');rect(x+3,y-14,4,5,'#c7735d');rect(x-4,y-4,3,2,'#ffe18a');rect(x+2,y-4,3,2,'#ffe18a')}else{rect(x-5,y+5,10,3,'#242a32');rect(x-6,y-5,12,11,'#385562');rect(x-5,y-10,10,7,'#5e7181');rect(x-4,y-5,3,2,'#cfedbf');rect(x+2,y-5,3,2,'#cfedbf')}
 if(f.hit>0){rect(x-8,y-16,16,3,'#251d29');rect(x-7,y-15,14*f.hp/f.max,1,'#f19271')}}

